(function(){"use strict";var stages=[["singapore","f-leg-sg","Singapur","Zahrady, světla a chutě Asie","Futuristická zátoka, tradiční čtvrti a večery mezi superstromy."],["uluwatu","f-leg-uluwatu","Bali · Uluwatu","Útesy nad Indickým oceánem","První balijské dny mezi plážemi, chrámy a západy slunce."],["ubud","f-leg-ubud","Bali · Ubud","Zelené srdce ostrova","Rýžové terasy, vodopády a čas na poznávání okolí Ubudu."],["lombokNorth","f-leg-lombok-sever","Lombok · západ a sever","Ostrovní rytmus a výlet na Gili","Moře, podvodní svět a poznávání Lomboku podle zvoleného programu."],["lombokSouth","f-leg-kuta","Kuta a Are Guling","Pláže, vyhlídky a volnější tempo","Jižní pobřeží Lomboku a prostor užít si cestu po svém."],["kutaLast","f-leg-rozlucka","Bali · rozloučení","Ještě jeden večer na Bali","Poslední noc před odletem, odpočinek a příprava na návrat."]];var descriptions=["Přelet ze Singapuru na Bali","Z Uluwatu do Ubudu","Z Bali na Lombok","Přesun na jih Lomboku","Z Lomboku zpět na Bali","Tranzit v Singapuru a cesta domů"];var unit="pers";function el(id){return document.getElementById(id)}function esc(s){return String(s==null?"":s).replace(/[&<>"']/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]})}function text(id){var node=el(id);return node?node.textContent.replace(/\s+/g," ").trim():""}function money(n){return Math.round(n).toLocaleString("cs-CZ")+" Kč"}function amount(id){var s=text(id);return/\d/.test(s)?Number(s.replace(/[^\d-]/g,"")):null}function url(value){try{var u=new URL(value,location.href);return/^https?:$/.test(u.protocol)?esc(u.href):""}catch(_){return""}}function image(src,alt,cls){return'<img class="'+cls+'" src="'+url(src)+'" alt="'+esc(alt)+'" loading="eager" decoding="async" width="640" height="440">'}function dates(stage){var fold=el(stage[1]);var sub=fold&&fold.querySelector(".lux-fold-s");return sub?sub.textContent.trim():""}function hotel(stage){try{return hotelCatalog[stage[0]].options[selectedHotels[stage[0]]]}catch(_){return null}}function cleanHeading(node){var clone=node.cloneNode(true);clone.querySelectorAll("button,.st-date").forEach(function(n){n.remove()});return clone.textContent.replace(/\s+/g," ").trim()}function program(stage){var fold=el(stage[1]);if(!fold)return"";var days=Array.from(fold.querySelectorAll("h4")).filter(function(h){return/\d+\.\s*DEN\s*:/i.test(h.textContent)});var rows=days.map(function(h){var label=cleanHeading(h).replace(/^[^\p{L}\d]+/u,"");var para=h.nextElementSibling;var detail=para&&para.tagName==="P"?para.textContent.trim():"";var day=h.querySelector(".st-date");return'<li><span class="sj-day-date">'+esc(day?day.textContent:"")+"</span><div><h4>"+esc(label)+"</h4>"+(detail?"<p>"+esc(detail)+"</p>":"")+"</div></li>"}).join("");return'<div class="sj-program"><h3>Program pobytu <span>'+(days.length?days.length+" "+(days.length===1?"den":days.length<5?"dny":"dní"):"podle itineráře")+"</span></h3>"+(rows?'<ol class="sj-days">'+rows+"</ol>":"")+"</div>"}function stageHtml(stage,index){var h=hotel(stage),choice=typeof selectedHotels!=="undefined"?selectedHotels[stage[0]]:"";var card=el("card-"+stage[0]+"-"+choice);var breakfast=card&&card.querySelector(".breakfast-badge");var room=h?money(h.price):"Cena není uvedena";return'<article class="sj-stage" id="sj-stage-'+index+'"><div class="sj-stage-top"><span class="sj-stage-number">'+String(index+1).padStart(2,"0")+'</span><div><p class="sj-eyebrow">'+esc(stage[2])+"</p><h2>"+esc(stage[3])+'</h2><p class="sj-muted">'+esc(dates(stage))+'</p></div></div><p class="sj-stage-intro">'+esc(stage[4])+"</p>"+'<div class="sj-hotel">'+(h&&h.img?'<figure class="sj-photo-mount">'+image(h.img,h.name,"sj-hotel-photo")+"<figcaption>"+esc(stage[2])+" · "+esc(h.name)+"</figcaption></figure>":"")+'<div class="sj-hotel-copy"><span class="sj-eyebrow">Naše adresa na cestě</span><h3>'+esc(h?h.name:stage[2])+'</h3><p class="sj-hotel-price">'+room+'</p><p class="sj-muted">za pokoj · celý pobyt'+(h?"<br>"+money(h.price/2)+" / osoba při sdílení pokoje":"")+"</p>"+(breakfast?'<p class="sj-breakfast">'+esc(breakfast.textContent)+"</p>":"")+"</div></div>"+program(stage)+"</article>"+'<div class="sj-transfer"><span aria-hidden="true">✧</span><div><small>Pokračujeme dál</small><p>'+esc(descriptions[index])+"</p>"+"</div></div>"}var budgetGroups=[["Letenky",["b1","b2"]],["Ubytování",["b4"]],["Lodě a skútry",["b3","b5"]],["Víza a poplatky",["b11","b12","b13","b14"]],["Jídlo",["bxFood"]],["Aktivity a další zvolené výdaje",["bxAct"]]];function budgetRows(){return budgetGroups.map(function(g){var n=g[1].reduce(function(sum,key){return sum+(amount(key+"_"+unit)||0)},0);return'<div class="sj-cost"><span>'+esc(g[0])+"</span><strong>"+money(n)+"</strong></div>"}).join("")}function flightHtml(){var f;try{f=flightOptions[currentAirline]}catch(_){return""}if(!f)return"";return'<div class="sj-flights"><div><span class="sj-eyebrow">Cesta tam</span><h3>Praha → Singapur</h3><p>'+esc(f.outDate)+" · "+esc(f.outDep)+" → "+esc(f.outArr)+"</p><small>Přestup: "+esc(f.outLayover)+'</small></div><div><span class="sj-eyebrow">Cesta zpět</span><h3>Singapur → Praha</h3><p>'+esc(f.retDate)+" · "+esc(f.retDep)+" → "+esc(f.retArr)+"</p><small>Přestup: "+esc(f.retLayover)+'</small></div></div><p class="sj-muted">Aktuální výběr: '+esc(f.name)+"</p>"}function build(options){var root=el("simplePage");if(root)root.classList.add("sj-page");unit="pers";var total=text("bxGrand_pers")||text("floatPricePerson")||"–";var cover="assets/images/external/8971dd33d4c37a53.webp";return'<main class="sj-book"><header class="sj-cover"><div class="sj-edition"><span>Soukromá cestovní edice</span><span>Srpen · 2027</span></div><div class="sj-cover-title"><span class="sj-compass" aria-hidden="true">✧</span><p class="sj-eyebrow">Deník jedné společné cesty</p><h1>Singapur<br><em>Bali &amp; Lombok</em></h1><p class="sj-cover-subtitle">Za světly města, zelení ostrovů a klidem oceánu.</p></div><figure class="sj-cover-photo">'+image(cover,"Balijský chrám u jezera mezi horami","sj-cover-image")+'<figcaption>Bali · ilustrační fotografie / Unsplash</figcaption></figure><div class="sj-cover-bottom"><span>6.—25. srpna 2027</span><span class="sj-seal">20 dní<br><i>na cestě</i></span><span>Singapur · Indonésie</span></div></header>'+'<div class="sj-container"><section class="sj-route"><div class="sj-section-title"><span class="sj-eyebrow">Prolog · Naše trasa</span><h2>Tři světy.<br><em>Jedna společná cesta.</em></h2><p>Z ruchu singapurských ulic k balijským chrámům. Přes zelené vnitrozemí až na pobřeží Lomboku. Šest zastavení, každé s jinou atmosférou.</p></div><ol class="sj-route-stops">'+stages.map(function(st,i){return"<li><span>"+String(i+1).padStart(2,"0")+"</span><div><strong>"+esc(st[2])+"</strong><small>"+esc(dates(st))+"</small></div></li>"}).join("")+'</ol><div class="sj-flight-details"><h3>První a poslední let</h3>'+flightHtml()+"</div></section>"+'<section class="sj-journey"><div class="sj-section-title"><span class="sj-eyebrow">Kapitoly cesty</span><h2>Místa, kde budeme <em>doma.</em></h2><p>Naše malé adresy na druhé straně světa a dny mezi nimi.</p></div><div class="sj-stages">'+stages.map(stageHtml).join("")+"</div></section>"+'<section class="sj-budget"><div class="sj-section-title"><span class="sj-eyebrow">Zápisník výdajů</span><h2>Na cestu <em>připraveno.</em></h2><p>Rozpočet podle zvolených hotelů, letů a programu.</p></div><div class="sj-budget-layout"><div class="sj-budget-total"><p class="sj-eyebrow">Na osobu · sdílený pokoj</p><strong>'+esc(total)+'</strong><p>Včetně plánovaného jídla a aktivit.</p><dl class="sj-price-notes"><div><dt>Za pár</dt><dd>'+esc(text("bxGrand_fam")||"–")+"</dd></div><div><dt>Samostatný pokoj · osoba</dt><dd>"+esc(text("bxGrand_sing")||"–")+'</dd></div></dl><small>Plánované výdaje bez vratných kaucí. Část hotovosti určená na útratu je v ceně již zahrnutá a nepřičítá se znovu.</small></div><div class="sj-budget-breakdown">'+budgetRows()+'</div></div><div class="sj-cash"><p><strong>Vratné kauce měj navíc v hotovosti.</strong> Na osobu při sdílení motorky ve dvou potřebuješ navíc 47,50 USD + přibližně 250 000 Rp; za celou motorku 95 USD + přibližně 500 000 Rp. V přehledu hotovosti už jsou kauce zahrnuté. Po vrácení motorek a splnění podmínek půjčoven dostaneš kauce zpět. Vrácené peníze můžeš využít jako rezervu na zbytek dovolené. Pokud je neutratíš, přivezeš si je zpátky domů.</p>'+(options.cashHtml||"")+"</div></section>"+'<footer class="sj-colophon"><span aria-hidden="true">✧</span><p>To nejkrásnější si přivezeme v sobě.</p><small>Singapur · Bali · Lombok<br>Soukromý cestovní deník · 6.—25. srpna 2027</small></footer></div></main>'}window.baliSimpleTravel={build:build}})();